fn solve(word: Vec<char>) -> Vec<char> {
    // Define the sets as arrays for easy membership checking
    let set_a: Vec<char> = vec!['A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z'];
    let set_b: Vec<char> = vec!['B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U'];

    // Check if the word is empty (though the problem states length is between 1 and 10)
    // requires: word.len() >= 1 && word.len() <= 10
    assert!(word.len() >= 1 && word.len() <= 10);
    
    // requires: word.len() > 0
    // ensures: return value is "YES" if all characters are in the same set, otherwise "NO"
    let result: Vec<char>;
    if word.is_empty() {
        result = "NO".chars().collect();
    } else {
        // Determine the set of the first character
        let is_in_set_a = set_a.contains(&word[0]);
        let is_in_set_b = set_b.contains(&word[0]);

        // Check if all characters belong to the same set
        for &ch in &word {
            // invariant: is_in_set_a || is_in_set_b
            if (is_in_set_a && !set_a.contains(&ch)) || (is_in_set_b && !set_b.contains(&ch)) {
                result = "NO".chars().collect();
                // ensures: result == "NO".chars().collect()
                return result;
            }
        }

        // If we reach here, all characters are in the same set
        result = "YES".chars().collect();
    }
    
    // ensures: result == "YES".chars().collect() || result == "NO".chars().collect()
    result
}